import React, { useState } from 'react'
import { useNavigate, Link } from 'react-router-dom'

export default function Register({ setUser }) {
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [confirm, setConfirm] = useState('')
  const [err, setErr] = useState('')
  const navigate = useNavigate()

  function submit(e) {
    e.preventDefault()

    if (password !== confirm) {
      setErr('Passwords do not match')
      return
    }

    const users = JSON.parse(localStorage.getItem('fl_users') || '[]')

    if (users.some(u => u.email === email)) {
      setErr('Email already in use')
      return
    }

    const u = { name, email, password }
    users.push(u)
    localStorage.setItem('fl_users', JSON.stringify(users))
    setUser({ name, email })
    navigate('/')
  }

  return (
    <div style={{ display: 'flex', height: '100vh' }}>

      {/* LEFT – BLUE BRAND SECTION */}
      <div
        style={{
          width: '50%',
          position: 'relative',
          background: 'linear-gradient(135deg, #0f172a, #1e3a8a)',
          color: '#fff',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          overflow: 'hidden'
        }}
      >
        {/* Decorative circles */}
        <div
          style={{
            position: 'absolute',
            width: 260,
            height: 260,
            borderRadius: '50%',
            background: 'rgba(255,255,255,0.06)',
            top: -60,
            left: -60
          }}
        />
        <div
          style={{
            position: 'absolute',
            width: 180,
            height: 180,
            borderRadius: '50%',
            background: 'rgba(255,255,255,0.05)',
            bottom: 60,
            right: 80
          }}
        />

        {/* Content */}
        <div style={{ textAlign: 'center', zIndex: 2 }}>
          <div style={{ fontSize: 52, fontWeight: 700, marginBottom: 12 }}>
            Finlance
          </div>

          <p style={{ maxWidth: 340, lineHeight: 1.7, opacity: 0.9 }}>
            Build healthy financial habits.<br />
            Plan smarter, save more,<br />
            and stay financially confident.
          </p>
        </div>
      </div>

      {/* RIGHT – REGISTER FORM */}
      <div
        style={{
          width: '50%',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          background: '#f4f6f8'
        }}
      >
        <div className="card" style={{ width: 420 }}>
          <h3 className="big">Create an account</h3>
          <p className="small">Sign up to start managing your finances</p>

          {err && (
            <div style={{ color: 'red', marginTop: 8 }}>
              {err}
            </div>
          )}

          <form onSubmit={submit} style={{ marginTop: 12 }}>
            <div style={{ marginBottom: 8 }}>
              <input
                className="input"
                placeholder="Full Name"
                value={name}
                onChange={e => setName(e.target.value)}
                required
              />
            </div>

            <div style={{ marginBottom: 8 }}>
              <input
                className="input"
                placeholder="Email"
                value={email}
                onChange={e => setEmail(e.target.value)}
                required
              />
            </div>

            <div style={{ marginBottom: 8 }}>
              <input
                className="input"
                type="password"
                placeholder="Password"
                value={password}
                onChange={e => setPassword(e.target.value)}
                required
              />
            </div>

            <div style={{ marginBottom: 12 }}>
              <input
                className="input"
                type="password"
                placeholder="Confirm Password"
                value={confirm}
                onChange={e => setConfirm(e.target.value)}
                required
              />
            </div>

            <button className="btn" style={{ width: '100%' }} type="submit">
              Create Account
            </button>
          </form>

          <div style={{ marginTop: 12 }} className="small">
            Already have an account? <Link to="/login">Login</Link>
          </div>
        </div>
      </div>

    </div>
  )
}
